package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.workflow.WorkflowProtocol;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;

/** Read-only recovery of the original AT07 result. The private dispatch proof is required;
 * a model, artifact ID or historical receipt cannot recreate current send/write authority. */
public final class TaskSourceVerifierReviewRecovery {
    private final JdbcTemplate db;private final TaskSourceVerifierSchema json;private final TaskSourceVerifierInvocationService invocations;
    private FormalCapabilityIdentityAuthority capabilities;
    @org.springframework.beans.factory.annotation.Autowired void evidenceCapabilities(FormalCapabilityIdentityAuthority value){capabilities=value;}
    private TaskReviewEvidenceContract contract(Context original)throws Exception {
        original.requireUnchanged();var ref=original.reference();var dispatch=original.dispatch();
        var row=one(db.queryForList("SELECT canonical_input,input_sha256 FROM task_source_verifier_input WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),dispatch.runId(),dispatch.stepId()));
        var payload=json.read(str(row,"canonical_input"));same(json.hash(payload),str(row,"input_sha256"));same(dispatch.inputSha256(),str(row,"input_sha256"));
        var b=payload.required("role_version");if(capabilities==null)bad();
        var role=capabilities.requireRegisteredIdentity(ref.tenantId(),original.admission().actorId(),new PermissionProtocol.Basis(text(b,"version_id"),text(b,"content_sha256")),"ROLE",ref.projectId());
        return TaskReviewEvidenceContract.require(role.canonicalDefinition().required("request"),SchemaCatalogue.fromClasspath());
    }
    public TaskSourceVerifierReviewRecovery(DataSource data,TaskSourceVerifierSchema json,TaskSourceVerifierInvocationService invocations){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.invocations=invocations;}
    public Optional<JsonNode> original(TaskSourceVerifierDispatchJournal.Original original)throws Exception{return read(new Original(original));}
    public Optional<JsonNode> stageFacts(TaskSourceVerifierDispatchJournal.StageFacts original)throws Exception{return read(new Stage(original));}
    /** Typed downstream access only after current StageFacts and full original physical verification. */
    ConsumerOutputs consumerOutputs(TaskSourceVerifierDispatchJournal.StageFacts proof)throws Exception {
        var context=new Stage(proof);var receipt=read(context).orElseThrow(()->new TenantAccessException(ErrorCode.STEP_NOT_READY));
        var findings=saved(context,text(receipt,"findings_artifact_id"),"REVIEW_FINDINGS",text(receipt,"action_id"));
        var coverage=saved(context,text(receipt,"coverage_artifact_id"),"REVIEW_COVERAGE",text(receipt,"action_id"));
        return new ConsumerOutputs(receipt,findings.payload,coverage.payload,findings.receipt,coverage.receipt,findings.object,coverage.object);
    }
    record ConsumerOutputs(JsonNode receipt,JsonNode findings,JsonNode coverage,JsonNode findingsReceipt,JsonNode coverageReceipt,
            InterfaceProtocol.ObjectRef findingsObject,InterfaceProtocol.ObjectRef coverageObject){}
    private sealed interface Context permits Original,Stage {
        void requireUnchanged()throws Exception;WorkflowProtocol.Reference reference()throws Exception;WorkflowProtocol.Dispatch dispatch()throws Exception;
        EnterpriseAccess.Admission admission()throws Exception;void provenance(JsonNode value)throws Exception;
    }
    private final class Original implements Context {
        private final TaskSourceVerifierDispatchJournal.Original proof;private Original(TaskSourceVerifierDispatchJournal.Original proof){this.proof=Objects.requireNonNull(proof);}
        public void requireUnchanged()throws Exception{proof.requireUnchanged();}public WorkflowProtocol.Reference reference(){return proof.reference();}public WorkflowProtocol.Dispatch dispatch(){return proof.dispatch();}public EnterpriseAccess.Admission admission(){return proof.admission();}public void provenance(JsonNode value)throws Exception{invocations.requireOriginalProvenance(proof,value);}
    }
    private final class Stage implements Context {
        private final TaskSourceVerifierDispatchJournal.StageFacts proof;private Stage(TaskSourceVerifierDispatchJournal.StageFacts proof){this.proof=Objects.requireNonNull(proof);}
        public void requireUnchanged()throws Exception{proof.requireUnchanged();}public WorkflowProtocol.Reference reference()throws Exception{return proof.reference();}public WorkflowProtocol.Dispatch dispatch()throws Exception{return proof.dispatch();}public EnterpriseAccess.Admission admission()throws Exception{return proof.admission();}public void provenance(JsonNode value)throws Exception{invocations.requireStageProvenance(proof,value);}
    }
    private Optional<JsonNode> read(Context original)throws Exception {
        original.requireUnchanged();var d=original.dispatch();var ref=original.reference();String actor=original.admission().actorId();
        var records=db.queryForList("SELECT * FROM task_source_verifier_submission WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),d.runId(),d.stepId());if(records.isEmpty())return Optional.empty();var row=one(records);var receipt=json.read(str(row,"receipt_json"));
        same(json.hash(receipt),str(row,"receipt_sha256"));same(actor,str(row,"created_by"));same(ref.tenantId(),text(receipt,"tenant_id"));same(d.runId(),text(receipt,"run_id"));same(d.stepId(),text(receipt,"step_id"));same(d.inputSha256(),text(receipt,"input_sha256"));same("N05",text(receipt,"node_kind"));same("CANDIDATE",text(receipt,"target_kind"));if(receipt.required("professional_approval").booleanValue())bad();
        for(String key:List.of("check_id","candidate_id","action_id","findings_artifact_id","coverage_artifact_id"))same(str(row,key),text(receipt,key));
        var findings=saved(original,text(receipt,"findings_artifact_id"),"REVIEW_FINDINGS",text(receipt,"action_id"));var coverage=saved(original,text(receipt,"coverage_artifact_id"),"REVIEW_COVERAGE",text(receipt,"action_id"));
        json.coverage(coverage.payload);same(findings.receiptHash,text(receipt,"findings_receipt_sha256"));same(coverage.receiptHash,text(receipt,"coverage_receipt_sha256"));same(findings.object.sha256(),text(coverage.payload,"findings_sha256"));
        for(String key:List.of("invocations","supervision","normalization","independent_reads"))same(findings.receipt.required("provenance").required(key),coverage.receipt.required("provenance").required(key));
        var full=ArtifactEvidenceBindings.bind(SchemaCatalogue.fromClasspath(),ArtifactBindings.ARTIFACT,findings.payload,contract(original).artifactRef(null),contract(original).artifactSha()).read();if(!(full.output() instanceof ArtifactProtocol.ReviewOutput))bad();var output=((ArtifactProtocol.ReviewOutput)full.output()).content();
        same(ref.tenantId(),full.tenantId());same(ref.projectId(),full.projectId());same(d.runId(),full.runId());same(d.stepId(),full.stepId());same(d.inputSha256(),full.inputManifestSha256());same(json.hash(full.output()),full.contentSha256());same(ArtifactProtocol.TargetKind.CANDIDATE,output.targetKind());same(output.targetRevision(),text(receipt,"target_revision"));same(output.targetSha256(),text(receipt,"target_sha256"));same(output.coverageComplete(),receipt.required("coverage_complete").booleanValue());same(output.coverageComplete(),coverage.payload.required("coverage_complete").booleanValue());
        var inputRow=one(db.queryForList("SELECT canonical_input,input_sha256 FROM task_source_verifier_input WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),d.runId(),d.stepId()));var input=json.input(str(inputRow,"canonical_input").getBytes(java.nio.charset.StandardCharsets.UTF_8));same(d.inputSha256(),json.hash(input));same(input.bodyArtifactId(),output.targetRevision());same(input.bodyObject().sha256(),output.targetSha256());same(input.candidateId(),text(receipt,"candidate_id"));same(input.ruleRevision(),output.ruleRevision());same(input.requiredClaimIds(),output.requiredClaimIds());same(input.requiredRules().stream().map(PermissionProtocol.Basis::version_id).toList(),output.requiredRuleIds());
        boolean blocked=!output.coverageComplete()||!output.issueProposals().isEmpty()||output.claimChecks().stream().anyMatch(c->c.supportCheck()==ArtifactProtocol.SupportCheck.CONTRADICTED||c.supportCheck()==ArtifactProtocol.SupportCheck.INSUFFICIENT)||output.ruleChecks().stream().anyMatch(r->r.result()==ArtifactProtocol.RuleResult.FAIL||r.result()==ArtifactProtocol.RuleResult.BLOCKED);same(blocked?"WAITING_INPUT":"SUCCEEDED",text(receipt,"status"));
        var check=one(db.queryForList("SELECT * FROM check_run WHERE tenant_id=? AND project_id=? AND check_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),text(receipt,"check_id")));same(input.candidateId(),str(check,"target_id"));same(input.bodyArtifactId(),str(check,"target_revision"));same(input.ruleRevision(),str(check,"rule_manifest_id"));same(d.inputSha256(),str(check,"input_sha256"));same(text(receipt,"findings_artifact_id"),str(check,"findings_artifact_id"));same(text(receipt,"coverage_artifact_id"),str(check,"coverage_artifact_id"));same(receipt,json.read(str(check,"result_ref")));
        var proposals=db.queryForList("SELECT proposal_id,proposal_json,proposal_sha256 FROM task_source_verifier_issue_proposal WHERE tenant_id=? AND project_id=? AND check_id=? ORDER BY proposal_id FOR UPDATE",ref.tenantId(),ref.projectId(),text(receipt,"check_id"));var ids=new HashSet<String>();var hashes=new HashSet<String>();for(var p:proposals){if(!ids.add(str(p,"proposal_id"))||!hashes.add(str(p,"proposal_sha256")))bad();same(json.hash(json.read(str(p,"proposal_json"))),str(p,"proposal_sha256"));}var expectedIds=new HashSet<String>();for(var id:receipt.required("issue_proposal_ids"))if(!expectedIds.add(id.asText()))bad();same(ids,expectedIds);var expectedHashes=new HashSet<String>();for(var issue:output.issueProposals())if(!expectedHashes.add(json.hash(issue)))bad();same(hashes,expectedHashes);
        audits(ref.tenantId(),actor,receipt,"task.source_verifier.review.submitted","candidate.review.recorded");original.requireUnchanged();return Optional.of(receipt.deepCopy());
    }
    private Saved saved(Context original,String id,String kind,String action)throws Exception {
        var d=original.dispatch();var ref=original.reference();String actor=original.admission().actorId();
        var r=one(db.queryForList("SELECT * FROM task_source_verifier_object WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND action_id=? AND artifact_id=? AND kind=? AND state='REGISTERED' LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),d.runId(),d.stepId(),action,id,kind));var receipt=json.read(str(r,"receipt_json"));var payload=json.read(str(r,"canonical_payload"));same(json.hash(receipt),str(r,"receipt_sha256"));same(json.hash(payload),str(r,"payload_sha256"));same(actor,str(r,"created_by"));same(id,text(receipt,"artifact_id"));same(d.inputSha256(),text(receipt,"input_sha256"));
        var intent=one(db.queryForList("SELECT * FROM task_source_verifier_object_intent WHERE tenant_id=? AND write_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),str(r,"write_id"),id));same(str(r,"canonical_payload"),str(intent,"canonical_payload"));same(str(r,"payload_sha256"),str(intent,"payload_sha256"));same(json.hash(json.read(str(intent,"intent_json"))),str(intent,"intent_sha256"));same(str(intent,"intent_sha256"),text(receipt,"intent_sha256"));var attempt=one(db.queryForList("SELECT intent_sha256 FROM task_source_verifier_object_attempt WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),str(r,"write_id")));same(str(intent,"intent_sha256"),str(attempt,"intent_sha256"));
        var o=receipt.required("object_ref");var object=new InterfaceProtocol.ObjectRef(text(o,"object_key"),text(o,"object_version"),text(o,"sha256"),o.required("size_bytes").asText(),text(o,"media_type"));var ar=one(db.queryForList("SELECT * FROM artifact WHERE tenant_id=? AND project_id=? AND artifact_id=? AND artifact_kind=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),id,kind));StoredObjectReferences.decode(str(ar,"object_ref"),object);same(object.sha256(),str(ar,"sha256"));same(object.objectVersion(),str(ar,"object_version"));same(object.sha256(),json.hash(payload));
        var provenance=receipt.required("provenance");same(action,text(provenance,"action_id"));same(kind,text(provenance,"kind"));same(object.sha256(),text(provenance,"payload_sha256"));original.provenance(provenance);independentReads(original,provenance.required("independent_reads"));
        same(object.sha256(),str(ar,"content_sha256"));same(d.runId(),str(ar,"run_id"));same(actor,str(ar,"created_by"));
        var binding=one(db.queryForList("SELECT * FROM artifact_content_binding WHERE tenant_id=? AND project_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),id));same("TASK",str(binding,"resource_kind"));same(str(ar,"dependency_access_set_id"),str(binding,"dependency_access_set_id"));
        var schema=SchemaCatalogue.fromClasspath();same(kind.equals("REVIEW_COVERAGE")?TaskSourceVerifierReviewService.COVERAGE_REF:contract(original).artifactRef(null),str(binding,"schema_ref"));same(kind.equals("REVIEW_COVERAGE")?TaskSourceVerifierReviewService.coverageManifest():contract(original).artifactSha(),str(binding,"schema_document_sha256"));
        var manifest=receipt.required("dependency_manifest");same(json.hash(manifest),str(binding,"dependency_manifest_sha256"));var registered=one(db.queryForList("SELECT manifest_json,manifest_sha256,content_sha256 FROM dependency_access_manifest WHERE tenant_id=? AND access_set_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),str(ar,"dependency_access_set_id")));same(manifest,json.read(str(registered,"manifest_json")));same(json.hash(manifest),str(registered,"manifest_sha256"));same(json.hash(manifest),str(registered,"content_sha256"));
        audits(ref.tenantId(),actor,receipt,"task.source_verifier.object.registered","task.source_verifier.object.registered");return new Saved(payload,receipt,object,str(r,"receipt_sha256"));
    }
    private void independentReads(Context original,JsonNode pins)throws Exception {
        var ref=original.reference();var dispatch=original.dispatch();String actor=original.admission().actorId(),session=text(pins,"session_id");same("N05_PHYSICAL_CONTEXT",text(pins,"kind"));same(dispatch.inputSha256(),text(pins,"input_sha256"));
        var row=one(db.queryForList("SELECT * FROM task_source_verifier_context_read WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND session_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),dispatch.runId(),dispatch.stepId(),session));same(actor,str(row,"created_by"));same(pins,json.read(str(row,"canonical_receipt")));same(json.hash(pins),str(row,"receipt_sha256"));
        var a=one(db.queryForList("SELECT resource_ref,subject_id,action,result FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),str(row,"audit_id")));same(pins,json.read(str(a,"resource_ref")));same(actor,str(a,"subject_id"));same("task.source_verifier.context.read",str(a,"action"));same("SUCCESS",str(a,"result"));
        var e=one(db.queryForList("SELECT payload,event_type FROM outbox_event WHERE tenant_id=? AND event_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),str(row,"event_id")));same(pins,json.read(str(e,"payload")));same("task.source_verifier.context.read",str(e,"event_type"));
        int count=0;for(String key:List.of("sources","rule_reads"))for(var read:pins.required(key)){count++;var child=one(db.queryForList("SELECT canonical_receipt,receipt_sha256,read_kind FROM task_source_verifier_independent_read WHERE tenant_id=? AND session_id=? AND receipt_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),session,text(read,"receipt_id")));same(read,json.read(str(child,"canonical_receipt")));same(json.hash(read),str(child,"receipt_sha256"));same(key.equals("sources")?"SOURCE":"RULE",str(child,"read_kind"));}
        same(count,db.queryForObject("SELECT COUNT(*) FROM task_source_verifier_independent_read WHERE tenant_id=? AND session_id=?",Integer.class,ref.tenantId(),session));
    }
    private void audits(String tenant,String actor,JsonNode receipt,String action,String eventType)throws Exception {var audit=one(db.queryForList("SELECT * FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2 FOR UPDATE",tenant,text(receipt,"audit_id")));same(receipt,json.read(str(audit,"resource_ref")));same("SUCCESS",str(audit,"result"));same(actor,str(audit,"subject_id"));same(action,str(audit,"action"));var event=one(db.queryForList("SELECT * FROM outbox_event WHERE tenant_id=? AND event_id=? LIMIT 2 FOR UPDATE",tenant,text(receipt,"event_id")));same(receipt,json.read(str(event,"payload")));same(eventType,str(event,"event_type"));}
    private record Saved(JsonNode payload,JsonNode receipt,InterfaceProtocol.ObjectRef object,String receiptHash){}
    private static <T>T one(List<T> rows){if(rows.size()!=1)bad();return rows.get(0);}private static String str(Map<String,Object> row,String key){var v=row.get(key);if(v==null)bad();return v.toString();}private static String text(JsonNode n,String key){return n.required(key).textValue();}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
